\node[black,anchor=north west,xshift=2pt,yshift=-3pt] at (7.3,0) {$k$};
\node[black,anchor=south west,xshift=2pt,yshift=2pt] at (0,9.2) {$\Delta$};
\draw[black,line width=0.8pt,dashed] plot[domain=\rootleft:\rootright,samples=81] (\x,{(\x-3)*(\x-3)-8});
\draw[positiveRed,line width=0.8pt,<-] plot[domain=-1:\rootleft,samples=41] (\x,{(\x-3)*(\x-3)-8});
\draw[positiveRed,line width=0.8pt,->] plot[domain=\rootright:7,samples=41] (\x,{(\x-3)*(\x-3)-8});
\draw[positiveRed,fill=white,line width=0.8pt] (\rootleft,0) circle[radius=1.3pt];
\draw[positiveRed,fill=white,line width=0.8pt] (\rootright,0) circle[radius=1.3pt];
\node[black,anchor=south west,xshift=2pt,yshift=4pt] at (\rootleft,0) {\special{dvisvgm:raw <g data-graph-text="tick">}$3-2\sqrt{2}$\special{dvisvgm:raw </g>}};
\node[black,anchor=south east,xshift=-2pt,yshift=4pt] at (\rootright,0) {\special{dvisvgm:raw <g data-graph-text="tick">}$3+2\sqrt{2}$\special{dvisvgm:raw </g>}};
